/* @lc app=leetcode id=1192 lang=kotlin */ class Solution { fun visit(vis: BooleanArray, pe: IntArray, ei: Int, v: Int): Boolean = !vis[v] && true.also { vis[v] = true }.also { pe[v] = ei } fun criticalConnections(n: Int, connections: List<List<Int>>): List<List<Int>> = Array(n) { ArrayList<Int>() }.also { adj -> connections.forEachIndexed { i, (a, b) -> adj[a].add(i).also { adj[b].add(i) } } }.let { adj -> IntArray(n) { -1 }.let { pe -> BooleanArray(n).also { it[0] = true }.let { vis -> generateSequence(listOf(0)) { f -> f.flatMap { u -> adj[u].filter { ei -> visit(vis, pe, ei, connections[ei][0] xor connections[ei][1] xor u) }.map { ei -> connections[ei][0] xor connections[ei][1] xor u } }.takeIf { it.isNotEmpty() } }.flatten().toList().let { order -> pe.filter { it >= 0 }.toSet().let { tree -> java.util.Random(12345).let { rnd -> LongArray(n).also { acc -> connections.indices.filter { it !in tree }.forEach { i -> rnd.nextLong().or(1L).let { v -> connections[i].forEach { acc[it] = acc[it] xor v } } } }.let { acc -> order.reversed().forEach { v -> if (pe[v] >= 0) (connections[pe[v]][0] xor connections[pe[v]][1] xor v).let { p -> acc[p] = acc[p] xor acc[v] } }.let { order.filter { pe[it] >= 0 && acc[it] == 0L }.map { connections[pe[it]] } } } } } } } } } }